import React, { useState } from 'react';
import { useData } from '../DataContext';

function Cadastro() {
  const { objetos, handleAddObjeto, handleRemoveObjeto } = useData();
  const [nomeCompleto, setNomeCompleto] = useState('');
  const [dataNascimento, setDataNascimento] = useState('');
  const [telefone, setTelefone] = useState('');

  const handleSubmit = (event) => {
    event.preventDefault();
    const novoObjeto = { 
      id: Date.now(), // Usando timestamp como ID único
      nomeCompleto, 
      dataNascimento, 
      telefone 
    };
    handleAddObjeto(novoObjeto); // Adiciona o novo objeto
    // Limpar os campos após adicionar
    setNomeCompleto('');
    setDataNascimento('');
    setTelefone('');
  };

  return (
    <div>
      <h1>Cadastro</h1>
      <form onSubmit={handleSubmit}>
        <label>
          Nome Completo:
          <input type="text" value={nomeCompleto} onChange={(e) => setNomeCompleto(e.target.value)} />
        </label>
        <br />
        <label>
          Data de Nascimento:
          <input type="date" value={dataNascimento} onChange={(e) => setDataNascimento(e.target.value)} />
        </label>
        <br />
        <label>
          Telefone:
          <input type="text" value={telefone} onChange={(e) => setTelefone(e.target.value)} />
        </label>
        <br />
        <button type="submit">Cadastrar</button>
      </form>

      <h2>Lista de Objetos</h2>
      <ul>
        {objetos.map((objeto) => (
          <li key={objeto.id}>
            {objeto.nomeCompleto} - {objeto.dataNascimento} - {objeto.telefone}
            <button onClick={() => handleRemoveObjeto(objeto.id)}>Remover</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default Cadastro;
